  flex-direction: row;
  align-items: center;
  justify-content: center;
}

[row][wrap] {
  flex-wrap: wrap;
}

[space=between] {
  justify-content: space-between;
}

[space=around] {
  justify-content: space-around;
}

[space=evenly] {
  justify-content: space-evenly;
}

[space=start] {
