section[auto] {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

section[auto] > * {
  flex: 1 1 100%;
}

@media (min-width: 768px) {
  section[auto] {
    flex-direction: row;
    flex-wrap: wrap;
    flex: 1 1 calc(50% - 1rem);
  }
}
