[grid] {
  display: grid;
}

[float=left] {
  float: left;
}

[badge] {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.375rem 0.75rem;
  border-radius: 999px;
  font-size: 0.8125rem;
  font-weight: 600;
  line-height: 1;
  border: 1px solid transparent;
  box-sizing: border-box;
}

[badge=square] {
  border-radius: 0.375rem;
}

[badge=ribbon] {
  position: absolute;
  top: -0.75rem;
  left: 50%;
  transform: translateX(-50%);
}

[banner] {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 1rem 1.5rem;
  border-radius: 0.75rem;
  box-sizing: border-box;
}

[banner=full] {
  width: 100%;
  border-radius: 0;
  padding: 1rem 2rem;
  justify-content: center;
}

button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.625rem 1.25rem;
  font: inherit;
  line-height: 1.2;
  cursor: pointer;
  box-sizing: border-box;
}

button[scale=sm] {
  padding: 0.4rem 0.875rem;
  font-size: 0.875rem;
}

button[scale=lg] {
  padding: 0.875rem 2rem;
  font-size: 1rem;
}

button[full] {
  width: 100%;
}

[btn=flat] {
  border-style: solid;
  text-align: center;
}
[btn=flat][theme=citrusmint-300] {
  background: hsl(121, 100%, 70%);
  color: hsl(121, 100%, 40%);
  border-color: hsl(121, 100%, 40%);
}
[btn=flat][theme=citrusmint-300]:hover {
  background: hsl(121, 100%, 40%);
  color: hsl(121, 100%, 90%);
  border-color: hsl(121, 100%, 90%);
}
[btn=flat][scale=lg] {
  padding: 0.875rem 2rem;
  font-size: 1rem;
}

[btn=outline] {
  border-style: solid;
  background: transparent;
  text-align: center;
}
[btn=outline][theme=citrusmint-300] {
  color: hsl(121, 100%, 70%);
  border-color: hsl(121, 100%, 70%);
}
[btn=outline][theme=citrusmint-300]:hover {
  background: hsl(121, 100%, 70%);
  color: hsl(121, 100%, 90%);
  border-color: hsl(121, 100%, 90%);
}
[btn=outline][scale=lg] {
  padding: 0.875rem 2rem;
  font-size: 1rem;
}

[btn=text] {
  background: transparent;
  text-align: center;
  border: none;
}
[btn=text][theme=citrusmint-300] {
  color: hsl(121, 100%, 70%);
}
[btn=text][theme=citrusmint-300]:hover {
  background: hsl(121, 100%, 70%);
  color: hsl(121, 100%, 90%);
}
[btn=text][scale=lg] {
  padding: 0.875rem 2rem;
  font-size: 1rem;
}

[btn="3d"] {
  background: hsl(121, 100%, 70%);
  color: hsl(121, 100%, 20%);
  border: none;
  box-shadow: 0 4px 0 0 hsl(121, 100%, 40%);
  text-align: center;
}
[btn="3d"]:hover {
  background: hsl(121, 100%, 40%);
  color: hsl(121, 100%, 90%);
  box-shadow: 0 2px 0 0 hsl(121, 100%, 90%);
  transform: translateY(2px);
}
[btn="3d"][scale=lg] {
  padding: 0.875rem 2rem;
  font-size: 1rem;
}

[btn=metallic] {
  background: linear-gradient(135deg, hsl(121, 100%, 70%), hsl(121, 100%, 40%), hsl(121, 100%, 70%));
  color: hsl(121, 100%, 90%);
