  text-align: center;
}
[btn=metallic]:hover {
  background: linear-gradient(135deg, hsl(121, 100%, 40%), hsl(121, 100%, 20%), hsl(121, 100%, 40%));
  color: hsl(121, 100%, 90%);
  box-shadow: 0 2px 0 0 hsl(121, 100%, 90%);
  transform: translateY(2px);
}
[btn=metallic][scale=lg] {
  padding: 0.875rem 2rem;
  font-size: 1rem;
}

[card] {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  height: auto;
  width: min(100%, 30vw);
  border-radius: 0.5rem;
  margin: 0 auto;
  padding: 1rem;
  box-sizing: border-box;
}

[card-large] {
  width: min(100%, 50vw);
}

[card-small] {
  width: min(100%, 15vw);
}

[card-size=sm] {
  width: min(100%, 15vw);
}

[card-size=md] {
  width: min(100%, 30vw);
}

[card-size=lg] {
  width: min(100%, 50vw);
}

[card-padding=sm] {
  padding: 0.75rem;
}

[card-padding=md] {
  padding: 1rem;
}

[card-padding=lg] {
  padding: 1.5rem;
}

[card=compact] {
  gap: 0.75rem;
  padding: 0.75rem;
}

[card=feature] {
  gap: 1.5rem;
  padding: 2rem;
  line-height: 1.8;
}

[card=interactive] {
  cursor: pointer;
  transition: transform 160ms ease, box-shadow 160ms ease, border-color 160ms ease;
}
[card=interactive]:hover {
  transform: translateY(-2px);
}
[card=interactive]:focus-within {
  transform: translateY(-2px);
}

[card=split] {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  align-items: stretch;
}

[card=cta] {
  gap: 1.5rem;
}

[card=pricing] {
  gap: 2rem;
  padding: 2.5rem;
  position: relative;
  border-width: 2px;
  border-style: solid;
  border-color: transparent;
}

[card=pricing][featured] {
  transform: scale(1.05);
}

@media (max-width: 768px) {
  [card=pricing][featured] {
    transform: none;
  }
}
[card-flow=horizontal] {
  flex-direction: row;
  align-items: center;
}

[card-flow=vertical] {
  flex-direction: column;
}

[card-header] {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

[card-header][row] {
  align-items: center;
}

[card-body] {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  min-width: 0;
  flex: 1 1 auto;
}

[card-media] {
  display: block;
  width: 100%;
  overflow: hidden;
  border-radius: inherit;
}

[card-actions] {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: auto;
}

[card-actions][center] {
  justify-content: center;
}

[card-actions][right] {
  justify-content: flex-end;
}

[card-meta] {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

[card-divider] {
  display: block;
  width: 100%;
  height: 1px;
  opacity: 0.12;
  background: currentColor;
}

[card=cta] [card-actions] {
  padding-top: 0.5rem;
}

[card=split] > [card-media] {
  height: 100%;
}

[card=split] > [card-body] {
  justify-content: center;
}

@media screen and (max-width: 768px) {
  [card] {
    width: 100%;
  }
  [card=split] {
    grid-template-columns: 1fr;
  }
}
[cta] {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 1.5rem;
  padding: 5rem 1.5rem;
  box-sizing: border-box;
}

[cta-title] {
  max-width: 44rem;
}

[cta-subtitle] {
  max-width: 38rem;
}

[cta-actions] {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1rem;
}

[cta-note] {
  font-size: 0.875rem;
  opacity: 0.85;
}

@media (max-width: 768px) {
  [cta] {
    padding: 3rem 1rem;
    gap: 1.25rem;
  }
}
/* =====================================================================
   Dashboard — logged-in customer cloud chrome
   Owns: shell, sidebar, nav, page-header, placeholder.
   Structure only — colors come from the theme.
   ===================================================================== */
[dashboard-shell] {
  display: flex;
  min-height: 100vh;
  height: 100vh;
  overflow: hidden;
}

[dashboard-sidebar] {
  width: 16rem;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  border-right: 1px solid;
  box-sizing: border-box;
}

[sidebar-brand] {
  display: flex;
  align-items: baseline;
  gap: 0.375rem;
  padding: 1.5rem 1.5rem 1.25rem;
  border-bottom: 1px solid;
}

[sidebar-brand] [logo] {
  font-weight: 700;
  font-size: 1.125rem;
  letter-spacing: -0.01em;
}

[sidebar-brand] [logo-suffix] {
  font-weight: 400;
  font-size: 0.875rem;
}

[sidebar-nav] {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: flex-start;
  gap: 0;
  padding: 1rem;
  overflow-y: auto;
  width: auto;
}

[nav-group] {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.125rem;
}

[nav-divider] {
  border: none;
  border-top: 1px solid;
  margin: 1rem 0;
}

[nav-link] {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.5rem 0.75rem;
  border-radius: 0.375rem;
  font-size: 0.875rem;
  font-weight: 500;
  text-decoration: none;
  transition: background-color 0.15s, color 0.15s;
}

[nav-link] > span {
  line-height: 1.2;
}

[sidebar-footer] {
  padding: 1rem 1.5rem;
  border-top: 1px solid;
  background: transparent;
}

[sidebar-footer] [version] {
  font-size: 0.75rem;
  margin: 0 0 0.25rem;
}

[sidebar-footer] [doc-link] {
  font-size: 0.75rem;
  text-decoration: none;
}

[dashboard-main] {
  flex: 1;
  overflow-y: auto;
  padding: 2.5rem 3rem;
  box-sizing: border-box;
}

[page-header] {
  margin-bottom: 2rem;
  border: none;
  padding: 0;
  background: transparent;
}

[page-header] > h1 {
  font-size: 2rem;
  line-height: 1.15;
  letter-spacing: -0.02em;
  margin: 0 0 0.5rem;
}

[page-header] > [lede] {
  font-size: 1rem;
  line-height: 1.5;
  margin: 0;
}

/* When the dashboard takes the page, hide the marketing nav + footer
   that wrap the routed content. Triggered purely by markup presence. */
[theme]:has([dashboard-shell]) > nav,
[theme]:has([dashboard-shell]) > footer {
  display: none;
}

[theme]:has([dashboard-shell]) > #page-content {
  height: 100vh;
  overflow: hidden;
}

/* =====================================================================
   Developers — developer hub landing page
   Owns: hero, quickstart card, categories grid, resources strip.
   Structure only — theme paints colors per tier.
   ===================================================================== */
/* Hero --------------------------------------------------------------- */
[developers-hero] {
  text-align: center;
}

[dev-hero-header] {
  max-width: 48rem;
  margin: 0 auto;
  background: transparent;
  border: none;
  padding: 0;
}

[dev-hero-header] > [badge] {
  display: inline-block;
  margin-bottom: 1.5rem;
}

[dev-hero-header] > h1 {
  font-size: 2.5rem;
  line-height: 1.1;
  letter-spacing: -0.02em;
  margin: 0 0 1.25rem;
}

@media (min-width: 1024px) {
  [dev-hero-header] > h1 {
    font-size: 3.25rem;
  }
}
[dev-hero-header] > [lede] {
  font-size: 1.125rem;
  line-height: 1.65;
  margin: 0 auto 2rem;
  max-width: 36rem;
}

[dev-hero-actions] {
  justify-content: center;
  flex-wrap: wrap;
}

[dev-hero-actions] > a {
  text-decoration: none;
}

[dev-hero-actions] button {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
}

/* Quickstart --------------------------------------------------------- */
[dev-quickstart] > [container][narrow] {
  max-width: 56rem;
  margin: 0 auto;
  padding: 0 1.5rem;
}

[quickstart-card] {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  align-items: center;
  padding: 2.5rem;
  border-radius: 1rem;
  border: 1px solid;
}

@media (max-width: 900px) {
  [quickstart-card] {
    grid-template-columns: 1fr;
    gap: 1.5rem;
  }
}
[quickstart-body] > [eyebrow] {
  display: inline-block;
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-weight: 600;
  margin: 0 0 0.75rem;
}

[quickstart-body] > h2 {
  font-size: 1.5rem;
  line-height: 1.2;
  margin: 0 0 0.5rem;
  letter-spacing: -0.01em;
}

[quickstart-body] > p {
  font-size: 0.9375rem;
  line-height: 1.55;
  margin: 0;
}

[code-block] {
  margin: 0;
  padding: 1.25rem 1.5rem;
  border-radius: 0.625rem;
  font-family: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  font-size: 0.8125rem;
  line-height: 1.6;
  overflow-x: auto;
  white-space: pre;
}

/* Install paths ------------------------------------------------------ */
[install-grid] {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(20rem, 1fr));
  gap: 1.25rem;
  max-width: 72rem;
  margin: 0 auto;
}

[install-card] {
  display: flex;
  flex-direction: column;
  gap: 0.875rem;
  padding: 2rem 1.75rem;
  border: 1px solid;
  border-radius: 0.875rem;
  background: transparent;
}

[install-card] [code-block] {
  margin-top: 0.5rem;
}

[install-icon] {
  width: 3rem;
  height: 3rem;
  border-radius: 0.625rem;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid;
  margin-bottom: 0.25rem;
}

[install-card] > h3 {
  font-size: 1.125rem;
  font-weight: 700;
  margin: 0;
  line-height: 1.3;
}

[install-card] > p {
  font-size: 0.9375rem;
  line-height: 1.55;
  margin: 0;
}

[install-footnote] {
  max-width: 48rem;
  margin: 2.5rem auto 0;
  text-align: center;
  font-size: 0.9375rem;
  line-height: 1.6;
}

/* Categories grid ---------------------------------------------------- */
[categories-grid] {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr));
  gap: 1.25rem;
  max-width: 72rem;
  margin: 0 auto;
}

[category-card] {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.875rem;
  padding: 2rem 1.75rem;
  border: 1px solid;
  border-radius: 0.875rem;
  cursor: pointer;
  transition: border-color 0.2s, transform 0.2s, box-shadow 0.2s;
  background: transparent;
}

[category-card]:hover {
  transform: translateY(-2px);
}

[category-icon] {
