/* =====================================================================
   Wizard — multi-step onboarding chrome
   Owns: shell, header, rails, step tracker, order summary, step pages,
         feature cards, pill, navigation. Structure only — colors live
         in the theme.
   ===================================================================== */
/* Shell --------------------------------------------------------------- */
[wizard-shell] {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  position: relative;
}

[wizard-header] {
  position: sticky;
  top: 0;
  z-index: 50;
  border-bottom: 1px solid;
  -webkit-backdrop-filter: blur(8px);
          backdrop-filter: blur(8px);
}

[wizard-header] > [container] {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 1.5rem;
  max-width: none;
  width: 100%;
  box-sizing: border-box;
}

[wizard-header] [brand] {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

[wizard-header] [brand] [logo] {
  font-weight: 700;
  font-size: 1.125rem;
  letter-spacing: -0.01em;
}

[wizard-header] [brand] [badge] {
  font-size: 0.75rem;
  padding: 0.25rem 0.625rem;
  border-radius: 0.375rem;
  font-weight: 500;
  line-height: 1.4;
}

/* Body layout — three column on xl, two on lg, single on md ----------- */
[wizard-body] {
  display: flex;
  flex: 1;
  position: relative;
  min-height: 0;
}

[wizard-rail=left] {
  display: none;
  flex-shrink: 0;
}
@media (min-width: 1024px) {
  [wizard-rail=left] {
    display: block;
    width: 20rem;
    border-right: 1px solid;
  }
}

[wizard-rail=right] {
  display: none;
  flex-shrink: 0;
}
@media (min-width: 1280px) {
  [wizard-rail=right] {
    display: block;
    width: 24rem;
    border-left: 1px solid;
  }
}

[wizard-content] {
  flex: 1;
  width: 100%;
  max-width: 64rem;
  margin: 0 auto;
  padding: 2rem 1.5rem;
  box-sizing: border-box;
}
@media (min-width: 1024px) {
  [wizard-content] {
    padding: 3rem;
  }
}

[wizard-content][data-step=provisioning],
[wizard-content][data-step=live] {
  padding: 0;
  max-width: none;
}

/* Step tracker (left rail) -------------------------------------------- */
[step-tracker] {
  padding: 2rem;
  position: sticky;
  top: 4rem;
}

[step-tracker] > header {
  margin-bottom: 2rem;
  border: none;
  padding: 0;
  background: transparent;
}

[step-tracker] [eyebrow] {
  font-size: 0.6875rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-weight: 600;
  margin: 0 0 0.5rem;
}

[step-tracker] > header > p {
  font-size: 0.8125rem;
  font-family: monospace;
  margin: 0;
}

[steps] {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 0;
}

[steps] > [step] {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 0.5rem 0;
}

/* Connector line between step indicators */
[steps] > [step]:not(:last-child)::after {
  content: "";
  position: absolute;
  left: calc(1.25rem - 1px);
  top: 3rem;
  width: 2px;
  height: 1rem;
}

[step-indicator] {
  width: 2.5rem;
  height: 2.5rem;
  border-radius: 50%;
  border: 2px solid;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 0.875rem;
  font-weight: 500;
  transition: background-color 0.2s, border-color 0.2s, color 0.2s;
}

[step-body] {
  flex: 1;
  padding-top: 0.375rem;
  min-width: 0;
}

[step-body] > h4 {
  font-size: 0.9375rem;
  font-weight: 500;
  margin: 0;
  line-height: 1.2;
}

[step-body] > p {
  font-size: 0.75rem;
  margin: 0.25rem 0 0;
  line-height: 1.4;
}

/* Order summary (right rail) ------------------------------------------ */
