  align-items: flex-start;
  gap: 0.75rem;
}

[mode-row] > div > p {
  font-size: 0.8125rem;
  font-weight: 500;
  margin: 0 0 0.25rem;
}

[mode-row] > div > p[subtle] {
  font-size: 0.75rem;
  font-weight: 400;
  margin: 0;
}

[summary-items] {
