/* Step pages ---------------------------------------------------------- */
[step-page] {
  max-width: 48rem;
}

[step-page] > h1,
[step-header] > h1 {
  font-size: 2.25rem;
  line-height: 1.1;
  letter-spacing: -0.02em;
  margin: 0 0 1rem;
