}

[step-header] {
  margin-bottom: 2rem;
}

/* Welcome page features */
[step-page=welcome] [features] {
  display: grid;
  gap: 1rem;
  margin-bottom: 3rem;
}

[feature] {
  display: flex;
  align-items: flex-start;
