/* Domain step summary */
[domain-summary] {
  margin-bottom: 1.5rem;
}

[selected-domain] {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 1rem 1.25rem;
  border: 1px solid;
  border-radius: 0.5rem;
