/* Generic eyebrow & subtle helpers used inside the wizard chrome */
[eyebrow] {
  font-size: 0.6875rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-weight: 600;
}

[subtle] {
  font-size: 0.875rem;
}

[workflow] {
  display: grid;
  grid-template-columns: 1fr auto 1fr auto 1fr;
  align-items: center;
  gap: 2rem;
  max-width: 64rem;
  margin: 0 auto;
