:root {
  /* GRADIENTS */
  /* Styles */
  --warm-to-cold: linear-gradient(90deg, hsl(0, 100%, 50%), hsl(240, 100%, 50%));
  --sunset: linear-gradient(90deg, hsl(30, 100%, 50%), hsl(330, 100%, 50%));
  --ocean: linear-gradient(90deg, hsl(200, 60%, 50%), hsl(200, 100%, 50%));
  --fire: linear-gradient(90deg, hsl(20, 100%, 50%), hsl(40, 100%, 50%));
  --forest: linear-gradient(90deg, hsl(120, 30%, 20%), hsl(120, 60%, 30%));
  --golden-hour: linear-gradient(90deg, hsl(30, 60%, 70%), hsl(40, 80%, 50%));
  --pastel-rainbow: linear-gradient(
          90deg,
          red 0%,
          yellow 20%,
          lime 40%,
          cyan 60%,
          blue 80%,
          magenta 100%,
          red 120%,
          yellow 140%
  );
  --muted-rainbow: linear-gradient(
      90deg,
      hsla(0, 100%, 50%, 0.7),
      hsla(45, 100%, 50%, 0.7),
      hsla(90, 100%, 50%, 0.7),
      hsla(135, 100%, 50%, 0.7),
      hsla(180, 100%, 50%, 0.7),
      hsla(225, 100%, 50%, 0.7),
      hsla(270, 100%, 50%, 0.7)
    );
  --contrast-rainbow: linear-gradient(
    90deg,
    hsl(0, 100%, 50%), /* Red */
    hsl(40, 100%, 50%), /* Orange */
    hsl(80, 100%, 50%), /* Yellow */
    hsl(120, 100%, 50%), /* Green */
    hsl(160, 100%, 50%), /* Cyan */
    hsl(200, 100%, 50%), /* Blue */
    hsl(240, 100%, 50%), /* Purple */
    hsl(280, 100%, 50%) /* Magenta */
  );
  /* Color Gradient Sets */
  --skylight: linear-gradient(90deg, hsl(210, 100%, 90%), hsl(210, 100%, 60%));
  --seaside: linear-gradient(90deg, hsl(180, 100%, 50%), hsl(240, 100%, 20%));
  --oceanspray: linear-gradient(90deg, hsl(200, 100%, 80%), hsl(240, 100%, 40%));
}

/* Gradient Base Styles */
body[gradient] {
  isolation: isolate;
}

[gradient] {
  /* display: inline-block; */
  position: relative;
  z-index: 0;
  /* background-size: cover; */
}

[gradient]:not([text]) {
  position: relative;
}

[gradient][text] {
  background: var(--grad-active);
  display: inline-block;
  -webkit-background-clip: text;
  -moz-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
}

[gradient]:not([text])::before {
  content: "";
  position: absolute;
  border-radius: inherit;
  inset: 0;
  z-index: -1;
  border-radius: inherit;
  background-image: var(--grad-active);
  background-size: cover;
  background-repeat: no-repeat;
  background-position: center;
}

body[gradient]:not([text])::before {
  background-size: 100% 100%;
}

body[gradient]:not([text])::before {
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: 0;
  background-size: 100% 100%;
  background-repeat: no-repeat;
  background-position: center;
}

/* Animation */
[gradient]:not([text])[motion=flow]::before,
[gradient]:not([text])[animation=flow]::before {
  background-size: 300% 100%;
  animation: gradShiftX 3s linear infinite;
}

button[gradient]:not([text])[motion=flow]::before,
button[gradient]:not([text])[animation=flow]::before {
  background-size: 800% 100%;
  animation: gradShiftX 8s linear infinite;
}

[text][motion=flow],
[text][animation=flow] {
  background-size: 800% 100%;
  animation: gradShiftX 8s linear infinite;
}

body[gradient]:not([text])[motion=fall]::before,
body[gradient]:not([text])[animation=fall]::before {
  background-size: 300% 300%;
  animation: gradShiftY 10s linear infinite;
}

@keyframes gradShiftX {
  0% {
    background-position: 0% 50%;
  }
  50% {
    background-position: 100% 50%;
  }
  100% {
    background-position: 0% 50%;
  }
}
@keyframes gradShiftY {
  0% {
    background-position: 50% 0%;
  }
  50% {
    background-position: 50% 100%;
  }
  100% {
    background-position: 50% 0%;
  }
}
